package com.zomiggy.controller; import com.zomiggy.dto.ApiDtos.*; import com.zomiggy.service.AuthService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/users/me") public class UserController {private final AuthService service; public UserController(AuthService s){service=s;} @GetMapping public Map<String,Object> get(Authentication a){return Map.of("user",toResponse(service.current(a.getName())));} @PatchMapping public Map<String,Object> patch(Authentication a,@Valid @RequestBody ProfileRequest r){var u=service.current(a.getName());u.setName(r.name());u.setAddress(r.address());return Map.of("user",toResponse(u));} private UserResponse toResponse(com.zomiggy.entity.User u){return new UserResponse(u.getId(),u.getName(),u.getMobile(),u.getAddress(),u.getCoins());}}